<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?= e($pageTitle??$themeName) ?></title><link rel="stylesheet" href="<?= e(site_url('themes/paper-cast/assets/style.css')) ?>"></head><body><header class="wrap header"><a class="brand" href="<?= e(site_url()) ?>">Paper Cast<span>.</span></a><nav><a href="<?= e(site_url()) ?>">Home</a><a href="<?= e(site_url('about.php')) ?>">About Us</a></nav><form action="<?= e(site_url('search.php')) ?>"><input name="q" placeholder="Search articles"><button>Search</button></form></header><main class="wrap"><section class="intro"><small>INDEPENDENT STORIES & IDEAS</small><h1>Ideas worth<br>reading.</h1><p>Thoughtful stories, fresh perspectives, and things worth sharing.</p></section><section class="grid"><?php foreach($posts as $post): ?><article><?php if($post['featured_image']): ?><img src="<?= e($post['featured_image']) ?>" alt=""><?php endif ?><small><?= e($post['category_name']??'Journal') ?></small><h2><a href="<?= e(site_url('article.php?slug='.rawurlencode($post['slug']))) ?>"><?= e($post['title']) ?></a></h2><p><?= e($post['excerpt']??'') ?></p></article><?php endforeach ?><?php if(!$posts): ?><p>No published stories yet.</p><?php endif ?></section></main><footer class="wrap footer">© <?= date('Y') ?> Paper Cast</footer></body></html>
